SCHEMA_VERSION = 4


def _columns(conn, table):
    return {row[1] for row in conn.execute(f"PRAGMA table_info({table})")}


def migrate(conn):
    """Idempotently extend the supplied v1 schema without replacing any rows."""
    conn.execute("PRAGMA foreign_keys=ON")
    conn.execute("BEGIN IMMEDIATE")
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL)")
        conn.execute("CREATE TABLE IF NOT EXISTS agents(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL)")
        conn.execute("""CREATE TABLE IF NOT EXISTS tickets(
            id INTEGER PRIMARY KEY, subject TEXT NOT NULL, body TEXT NOT NULL,
            status TEXT NOT NULL, priority TEXT NOT NULL,
            assignee_id INTEGER REFERENCES agents(id), requester_email TEXT NOT NULL,
            created_at TEXT NOT NULL, updated_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS comments(
            id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES tickets(id),
            author_email TEXT NOT NULL, author_type TEXT NOT NULL, body TEXT NOT NULL,
            created_at TEXT NOT NULL)""")
        tcols = _columns(conn, "tickets")
        for name in ("external_message_id", "sla_due_at", "reopened_at", "closed_at"):
            if name not in tcols:
                conn.execute(f"ALTER TABLE tickets ADD COLUMN {name} TEXT")
        if "external_message_id" not in _columns(conn, "comments"):
            conn.execute("ALTER TABLE comments ADD COLUMN external_message_id TEXT")
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS tickets_message_id ON tickets(external_message_id) WHERE external_message_id IS NOT NULL")
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS comments_message_id ON comments(external_message_id) WHERE external_message_id IS NOT NULL")
        conn.execute("CREATE INDEX IF NOT EXISTS tickets_status_assignee ON tickets(status, assignee_id, id)")
        conn.execute("CREATE INDEX IF NOT EXISTS comments_ticket ON comments(ticket_id, id)")
        conn.execute("""CREATE TABLE IF NOT EXISTS imported_messages(
            message_id TEXT PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES tickets(id),
            comment_id INTEGER REFERENCES comments(id), source TEXT NOT NULL)""")
        conn.execute("CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL)")
        # Existing v1 tickets gain the same deterministic SLA calculation as new ones.
        from .sla import due_at
        for row in conn.execute("SELECT id,created_at,priority FROM tickets WHERE sla_due_at IS NULL"):
            conn.execute("UPDATE tickets SET sla_due_at=? WHERE id=?", (due_at(row["created_at"], row["priority"]), row["id"]))
        conn.execute("DELETE FROM schema_version")
        conn.execute("INSERT INTO schema_version(version) VALUES (?)", (SCHEMA_VERSION,))
        conn.commit()
    except BaseException:
        conn.rollback()
        raise
from datetime import datetime, timezone, timedelta


def parse(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("timestamp must be an RFC 3339 string")
    text = value.strip()
    try:
        dt = datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith(("Z", "z")) else text)
    except ValueError as exc:
        raise ValueError("invalid RFC 3339 timestamp") from exc
    if dt.tzinfo is None:
        raise ValueError("timestamp must include a UTC offset")
    return dt.astimezone(timezone.utc)


def format_utc(dt):
    dt = dt.astimezone(timezone.utc)
    if dt.microsecond:
        value = dt.isoformat(timespec="microseconds").rstrip("0").rstrip(".")
    else:
        value = dt.isoformat(timespec="seconds")
    return value.replace("+00:00", "Z")


def normalize(value):
    return format_utc(parse(value))


def add_business_hours(value, hours, start_hour=9, end_hour=17):
    current = parse(value)
    if current.weekday() >= 5 or current.hour >= end_hour:
        current = (current + timedelta(days=1)).replace(hour=start_hour, minute=0, second=0, microsecond=0)
    elif current.hour < start_hour:
        current = current.replace(hour=start_hour, minute=0, second=0, microsecond=0)
    while current.weekday() >= 5:
        current += timedelta(days=1)
    remaining = timedelta(hours=hours)
    while remaining:
        close = current.replace(hour=end_hour, minute=0, second=0, microsecond=0)
        available = close - current
        if remaining <= available:
            current += remaining
            break
        remaining -= max(available, timedelta())
        current = (current + timedelta(days=1)).replace(hour=start_hour, minute=0, second=0, microsecond=0)
        while current.weekday() >= 5:
            current += timedelta(days=1)
    return format_utc(current)
